// By Astra; OpenAI Codex (GPT-6), 2026-10-16. Local planning; no model or Unity execution.
(()=>{'use strict';const data=JSON.parse(document.getElementById('world-data').textContent),$=id=>document.getElementById(id),KEY='the-threshold-backlog';
  const blank=()=>({schema:1,program:'the-threshold',floors:{},notes:[],tools:{},project:null});let state=blank();
  function validate(x){if(!x||x.schema!==1||x.program!=='the-threshold'||!x.floors||typeof x.floors!=='object'||Array.isArray(x.floors)||!Array.isArray(x.notes)||x.notes.length>500)throw Error('Choose a Threshold v1 backup.');const out=blank();for(const [id,f]of Object.entries(x.floors)){if(!data.scenes.some(s=>String(s.number)===id)||!f||typeof f.selected!=='boolean'||!['concept','building','needs-review'].includes(f.stage))throw Error('Invalid floor data.');out.floors[id]={selected:f.selected,stage:f.stage};}for(const n of x.notes){if(!n||typeof n.id!=='string'||n.id.length>100||typeof n.text!=='string'||n.text.length>8000||!Number.isFinite(Date.parse(n.at)))throw Error('Invalid note.');out.notes.push({id:n.id,text:n.text,at:n.at});}for(const id of ['floor-planner','build-request','tutorials','notes']){const t=x.tools?.[id];if(t)out.tools[id]={enabled:t.enabled!==false,maintenance:t.maintenance===true};}if(x.project){if(typeof x.project.name!=='string'||x.project.name.length>160||typeof x.project.version!=='string'||x.project.version.length>80)throw Error('Invalid project metadata.');out.project={name:x.project.name,version:x.project.version};}return out;}
  let unreadable=null;
  try{const saved=localStorage.getItem(KEY);if(saved){unreadable=saved;state=validate(JSON.parse(saved));unreadable=null;}}catch{$('note-message').textContent='Saved data could not be read. The original will be retained in a recovery copy before any replacement.';}
  function retainRecovery(){if(unreadable!==null){localStorage.setItem(KEY+':recovery:'+new Date().toISOString(),unreadable);unreadable=null;}}
  function save(){try{retainRecovery();localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{$('note-message').textContent='Storage is unavailable or full. Export your changes before closing.';return false;}}
  const enabled=id=>state.tools[id]?.enabled!==false;
  function download(name,value){const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Denver',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()).replaceAll('-','');const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name+'-'+day+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
  function render(){const q=$('floor-search').value.toLowerCase(),filter=$('plan-filter').value;const total=data.scenes.filter(s=>state.floors[s.number]?.selected).length;$('plan-count').textContent=total+' selected / '+data.scenes.length+' concepts';$('plan-grid').replaceChildren();for(const s of data.scenes){const f=state.floors[s.number]||{selected:false,stage:'concept'};if(!(s.animal+' '+s.environment).toLowerCase().includes(q)||filter==='selected'&&!f.selected||filter==='needs-review'&&f.stage!=='needs-review')continue;const a=document.createElement('article');a.className='floor';a.id='floor-'+s.number;const box=document.createElement('div');box.className='floor-copy';const h=document.createElement('h3');h.textContent=String(s.number).padStart(2,'0')+' · '+s.animal;const p=document.createElement('p');p.textContent=s.environment;const link=document.createElement('a');link.href='liminal-doors-20261016.html#floor-'+s.number;link.textContent='Preview floor ↗';const label=document.createElement('label');label.className='status-label';const check=document.createElement('input');check.type='checkbox';check.checked=f.selected;check.disabled=!enabled('floor-planner');check.setAttribute('aria-label','Select '+s.animal+' for first build');check.onchange=()=>{if(!enabled('floor-planner'))return;state.floors[s.number]={...f,selected:check.checked};save();render();};label.append(check,document.createTextNode(' First build shortlist'));const select=document.createElement('select');select.setAttribute('aria-label',s.animal+' build status');for(const [value,text]of [['concept','Concept'],['building','Building (your mark)'],['needs-review','Needs review (your mark)']]){const option=document.createElement('option');option.value=value;option.textContent=text;select.append(option);}select.value=f.stage;select.disabled=!enabled('floor-planner');select.onchange=()=>{if(!enabled('floor-planner'))return;state.floors[s.number]={...f,stage:select.value};save();render();};box.append(h,p,link,label,select);a.append(box);$('plan-grid').append(a);}
    $('backlog').replaceChildren();for(const n of state.notes.slice(-30).reverse()){const p=document.createElement('p');p.className='backlog-entry';p.textContent=new Date(n.at).toLocaleString()+'\n'+n.text;$('backlog').append(p);}
    $('unity-state').textContent=state.project?state.project.name+' · Unity '+state.project.version+' · Folder metadata inspected; no live editor connection.':'No production world project connected. The existing glass-tool test scene is a prototype fixture.';
  }
  for(const section of document.querySelectorAll('[data-tool]')){const id=section.dataset.tool,lights=document.createElement('div');lights.className='lights';const power=document.createElement('button'),health=document.createElement('button');health.className='maintenance';const update=()=>{const t=state.tools[id]||{enabled:true,maintenance:false};for(const [b,on,label]of [[power,t.enabled,'On'],[health,t.maintenance,'Needs maintenance']]){b.dataset.on=String(on);b.setAttribute('aria-pressed',String(on));b.setAttribute('aria-label',id+': '+(b===power?(on?'On':'Off'):(on?'Needs maintenance':'Working')));b.title=b.getAttribute('aria-label');}section.dataset.enabled=String(t.enabled);for(const e of section.querySelectorAll('.tool-body button,.tool-body input,.tool-body textarea,.tool-body select'))e.disabled=!t.enabled;};power.onclick=()=>{const t=state.tools[id]||{enabled:true,maintenance:false};state.tools[id]={...t,enabled:!t.enabled};save();render();update();};health.onclick=()=>{const t=state.tools[id]||{enabled:true,maintenance:false};state.tools[id]={...t,maintenance:!t.maintenance};save();update();};lights.append(power,health);section.prepend(lights);update();}
  $('floor-search').oninput=render;$('plan-filter').onchange=render;
  $('save-note').onclick=()=>{if(!enabled('notes'))return;const text=$('note').value.trim();if(!text){$('note-message').textContent='Write an idea before saving.';return;}if(state.notes.length>=500){$('note-message').textContent='Backlog limit reached. Export your notes before adding more.';return;}state.notes.push({id:crypto.randomUUID(),at:new Date().toISOString(),text});if(save()){$('note').value='';$('note-message').textContent='Saved to your local backlog.';}render();};
  $('export-backup').onclick=()=>{if(enabled('build-request'))download('the-threshold-backup',state);};
  $('export-request').onclick=()=>{if(enabled('build-request')){download('the-threshold-unity-request',{schema:1,owner:'Door Dormouse',program:'The Threshold',world:'Liminal Doors',build_tools_owner:'Unity Unicorn',constraints:data.constraints,floors:data.scenes.filter(s=>state.floors[s.number]?.selected),notes:state.notes});$('backup-message').textContent='Request exported. Hand it to Unity Unicorn; no agent was started.';}};
  $('restore').onchange=async()=>{if(!enabled('build-request'))return;const file=$('restore').files?.[0];if(!file)return;try{if(file.size>32000000)throw Error('Backup exceeds 32 MB.');const incoming=validate(JSON.parse(await file.text()));if(!enabled('build-request'))return;const notes=new Map(state.notes.map(n=>[n.id,n]));for(const n of incoming.notes)if(!notes.has(n.id))notes.set(n.id,n);if(notes.size>500)throw Error('Combined backlog exceeds 500 notes.');const next={...state,floors:{...state.floors,...incoming.floors},notes:[...notes.values()],project:state.project||incoming.project};retainRecovery();localStorage.setItem(KEY,JSON.stringify(next));state=next;$('backup-message').textContent='Backup merged; existing notes and current tool controls retained.';render();}catch(e){$('backup-message').textContent='Import not applied: '+e.message;}finally{$('restore').value='';}};
  $('unity-folder').onchange=async()=>{const files=[...$('unity-folder').files];try{const version=files.find(f=>/\/ProjectSettings\/ProjectVersion\.txt$/.test(f.webkitRelativePath)),manifest=files.find(f=>/\/Packages\/manifest\.json$/.test(f.webkitRelativePath));if(!version||!manifest||version.size>10000||manifest.size>100000)throw Error('Select a Unity project containing ProjectSettings/ProjectVersion.txt and Packages/manifest.json.');const match=(await version.text()).match(/m_EditorVersion:\s*([^\r\n]+)/);const pkg=JSON.parse(await manifest.text());if(!match||!pkg.dependencies)throw Error('Unity project metadata is incomplete.');state.project={name:version.webkitRelativePath.split('/')[0],version:match[1].trim()};if(save())$('connection-message').textContent='Project metadata linked locally. Unity execution and world validation remain separate.';render();}catch(e){$('connection-message').textContent=e.message;}};
  for(const b of document.querySelectorAll('.tutorial'))b.onclick=()=>{if(!enabled('tutorials'))return;$('tutorial-message').textContent=b.dataset.guide==='play'?'1. Open the preview. 2. Shortlist floors. 3. Export a build request. 4. Keep corrections in Notes. Guided chat remains disconnected.':'1. Export a backup. 2. Review incomplete tool requirements. 3. Check real Unity and headset evidence before changing readiness. No weekly worker is configured.';};
  $('pet-open').onclick=()=>$('pet').showModal();$('close-chat').onclick=()=>$('pet').close();render();if(/^#floor-\d+$/.test(location.hash))document.querySelector(location.hash)?.scrollIntoView();
})();
